"""Compute the difference between the sum of squares and the square of
    the sum of the natural numbers up to and including the provided ceiling.
    """
def sum_square_difference(ceiling: Any) -> object {
    numbers = range((ceiling + 1));
    sum_squares = sum(map(lambda (number: Any) { (number ** 2); }, numbers));
    square_sum = sum(numbers) ** 2;
    sum_square_difference = square_sum - sum_squares;
    return sum_square_difference;
}

"""Update the value of `x` by adding `increment`.

    # Arguments
        x: A `Variable`.
        increment: A tensor of same shape as `x`.

    # Returns
        The variable `x` updated.
    """
def update_add(x: Any, increment: Any) -> object {
    return (x, (x + increment));
}

"""
    Returns price including vat amount, and vat amount
    """
def add_vat(price: Any, vat: Any) -> object {
    vat_paid = price * (vat / 100);
    return ((price + vat_paid), vat_paid);
}

"""
    >>> _changes([2, 3, 0, 5])
    [2, 1, -3, 5]
    >>> _changes([2])
    [2]
    """
def _changes(path: Any) -> object {
    res = [path[0]];
    res += [(p - p_prev) for (p, p_prev) in zip(path[1:], path)];
    return res;
}

"""turn a primer dict from primer3 in fastCloningPrimer to the NEB readdable format"""
def primerDictToNEBPrimerSeq(primerDict: Any) -> object {
    NEBPrimerString = "";
    for (primerPairName, primerPairInfo) in primerDict.items() {
        currentLPrimerName = str(primerPairName) + "Left";
        currentLPrimerSeq = primerPairInfo[0][2];
        currentRPrimerName = str(primerPairName) + "Right";
        currentRPrimerSeq = primerPairInfo[1][2];
        NEBPrimerString += (
            currentLPrimerName
            + "; "
            + currentLPrimerSeq
            + "; "
            + currentRPrimerName
            + "; "
            + currentRPrimerSeq
            + "\n"
        );
    }
    return NEBPrimerString;
}

"""
    Converts a list of enums into a delimited string using the enum values
    E.g., [PlayerActionEnum.FLYBALL, PlayerActionEnum.HOMERUN, PlayerActionEnum.WALK] = 'FLYBALL,HOMERUN,WALK'
    :param enumlist:
    :param delimiter:
    :return:
    """
def convert_enum_list_to_delimited_string(
    enumlist: Any, delimiter: Any = ','
) -> object {
    return delimiter.join([listitem.value for listitem in enumlist]);
}

"""Checks if a matrix is symmetrical"""
def is_symmetrical(matrix: Any) -> object {
    result = True;
    for i in range(8) {
        row = matrix[(i * 8):((i + 1) * 8)];
        result = result and (row[0:3] == row[4:]);
    }
    return result;
}
